static const char* b2s(bool b) { return b ? "True" : "False"; }

struct Empty {};
struct NonVirtual { void g() {} };

struct Animal {
    virtual std::string name() const { return "Animal"; }
    virtual ~Animal() = default;
};
struct Dog : Animal {
    std::string name() const override { return "Dog"; }
};

static std::string describe(const Animal& a) { return a.name(); }   // 动态绑定

int main() {
    std::cout << "sizeof(Empty)=" << sizeof(Empty) << "\n";
    std::cout << "sizeof(NonVirtual)=" << sizeof(NonVirtual) << "\n";

    bool hasVptr = sizeof(Animal) > sizeof(NonVirtual);
    std::cout << "polymorphic class carries vptr=" << b2s(hasVptr) << "\n";

    Animal animal;
    Dog dog;
    std::cout << "static type Animal -> " << describe(animal) << "\n";
    std::cout << "static type Dog -> " << describe(dog) << "\n";

    Animal* p = &dog;                       // 基类指针指向派生对象
    std::cout << "via base pointer -> " << p->name() << "\n";

    Animal sliced = dog;                    // 对象切片：丢失派生部分
    std::cout << "after slicing -> " << sliced.name() << "\n";

    Animal& r = dog;                        // 引用不切片
    std::cout << "via base reference -> " << r.name() << "\n";

    std::cout << "vptr is per-class shared: " << b2s(sizeof(Animal) == sizeof(Dog)) << "\n";
}
